import { findById, validateExists } from './users.js';
import { canDelete } from './permissions.js';
import { Cache } from './cache.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

const STATUS_TRANSITIONS: Record<Task['status'], Task['status'][]> = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

const taskCache = new Cache();

class TaskManager {
  private tasks = new Map<string, Task>();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    // Validate title is non-empty.
    if (!input.title.trim()) {
      throw new Error('Task title must not be empty');
    }

    // Validate both createdBy and assignee refer to existing users.
    if (!validateExists(input.createdBy)) {
      throw new Error(`User "${input.createdBy}" does not exist`);
    }
    if (!validateExists(input.assignee)) {
      throw new Error(`User "${input.assignee}" does not exist`);
    }

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };

    this.tasks.set(task.id, task);
    record({ action: 'create', userId: input.createdBy, taskId: task.id, timestamp: Date.now() });
    return task;
  }

  getTask(id: string): Task | null {
    // Try cache first.
    const cached = taskCache.get<Task | null>(id);
    if (cached !== null) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      taskCache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = STATUS_TRANSITIONS[task.status];
    if (!allowed.includes(status)) {
      throw new Error(`Invalid status transition: ${task.status} -> ${status}`);
    }

    task.status = status;
    taskCache.invalidate(id);
    record({ action: 'status_change', userId: task.createdBy, taskId: id, timestamp: Date.now() });
    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) {
      return false;
    }

    this.tasks.delete(id);
    taskCache.invalidate(id);
    record({ action: 'delete', userId, taskId: id, timestamp: Date.now() });
    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
", "path": "src/tasks.ts"}

